986	// Venda balcão — comanda avulsa (sem mesa/cliente) com layout tipo PDV de mercado:
987	// catálogo de produtos de um lado, carrinho + pagamento do outro. Reaproveita os
988	// mesmos endpoints de comanda (itens, desconto/acréscimo, pagamento parcial,
989	// pagar) — o cliente pode dividir o pagamento em pix + dinheiro + cartão na mesma
990	// venda, cada parcela com sua própria taxa de cartão quando for o caso.
991	const VendaBalcaoModal = ({ comandaId, onFechar, onMudou }) => {
992	  const [comanda, setComanda] = useState(null);
993	  const [produtos, setProdutos] = useState([]);
994	  const [busca, setBusca] = useState('');
995	  const [categoria, setCategoria] = useState('todas');
996	  const [produtoAtivo, setProdutoAtivo] = useState(null);
997	
998	  const [descontoInput, setDescontoInput] = useState('');
999	  const [acrescimoInput, setAcrescimoInput] = useState('');
1000	  const [taxaCartaoPercentual, setTaxaCartaoPercentual] = useState(0);
1001	
1002	  const [valorPagamento, setValorPagamento] = useState('');
1003	  const [formaPagamentoParcial, setFormaPagamentoParcial] = useState('pix');
1004	  const [valorRecebidoParcial, setValorRecebidoParcial] = useState('');
1005	
1006	  const [forma, setForma] = useState('pix');
1007	  const [valorRecebidoFinal, setValorRecebidoFinal] = useState('');
1008	
1009	  const [erro, setErro] = useState(null);
1010	  const [salvando, setSalvando] = useState(false);
1011	
1012	  const carregar = useCallback(async () => {
1013	    const c = await getSalaoComandaDetalhe(comandaId);
1014	    setComanda(c);
1015	    setDescontoInput(String(c.desconto_valor ?? 0));
1016	    setAcrescimoInput(String(c.acrescimo_valor ?? 0));
1017	  }, [comandaId]);
1018	
1019	  useEffect(() => { carregar(); }, [carregar]);
1020	  useEffect(() => {
1021	    getMeusProdutos().then((d) => setProdutos(d.produtos ?? [])).catch(() => {});
1022	    getConfig().then((c) => setTaxaCartaoPercentual(c.taxa_cartao_percentual ?? 0)).catch(() => {});
1023	  }, []);
1024	
1025	  const isCartao = (f) => f === 'credit_card' || f === 'debit_card';
1026	
1027	  const acao = async (fn) => {
1028	    setErro(null);
1029	    setSalvando(true);
1030	    try {
1031	      await fn();
1032	      await carregar();
1033	      onMudou();
1034	    } catch (err) {
1035	      setErro(err.message);
1036	    } finally {
1037	      setSalvando(false);
1038	    }
1039	  };
1040	
1041	  const adicionar = (item) => acao(() => adicionarItensComandaSalao(comandaId, [item]));
1042	
1043	  const alterarQuantidade = (item, delta) => {
1044	    const novaQtd = item.quantity + delta;
1045	    if (novaQtd < 1) {
1046	      acao(() => removerItemComandaSalao(comandaId, item.id));
1047	      return;
1048	    }
1049	    acao(() => editarItemComandaSalao(comandaId, item.id, { quantity: novaQtd }));
1050	  };
1051	
1052	  const removerItem = (item) => acao(() => removerItemComandaSalao(comandaId, item.id));
1053	
1054	  const aplicarDesconto = () => acao(() => aplicarDescontoComanda(comandaId, Number(descontoInput || 0)));
1055	  const aplicarAcrescimo = () => acao(() => aplicarAcrescimoComanda(comandaId, Number(acrescimoInput || 0)));
1056	
1057	  const registrarPagamento = () => {
1058	    const v = Number(valorPagamento);
1059	    if (!v || v <= 0) return;
1060	    if (formaPagamentoParcial === 'cash' && valorRecebidoParcial && Number(valorRecebidoParcial) < v) {
1061	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
1062	      return;
1063	    }
1064	    acao(async () => {
1065	      await registrarPagamentoParcialSalao(
1066	        comandaId, v, formaPagamentoParcial,
1067	        formaPagamentoParcial === 'cash' && valorRecebidoParcial ? Number(valorRecebidoParcial) : undefined,
1068	      );
