4	import { printTicketSetor } from '../../utils/printComanda';
5	import { formatDuracao } from '../../utils/formatDuracao';
6	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
7	import { useNowTick } from '../../hooks/useNowTick';
8	import Icon from '../../components/AppIcon';
9	
10	// Card por item (não por mesa/comanda) com cronômetro ao vivo — mostra há quanto tempo
11	// o item chegou (aguardando) e, quando em preparo, há quanto tempo está preparando,
12	// pra dar visibilidade do tempo total gasto até ficar pronto.
13	const ItemCard = ({ item, posicao, now, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar, onCancelar, onAbrirComanda }) => {
14	  const enviadoEm = new Date(item.enviado_em).getTime();
15	  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
16	  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
17	  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
18	  const tempoTotal = now - enviadoEm;
19	  const podeAbrirComanda = item.tipo === 'salao' && !!item.numero_comanda;
20	
21	  return (
22	    <div
23	      onClick={podeAbrirComanda ? () => onAbrirComanda(item.order_id) : undefined}
24	      title={podeAbrirComanda ? 'Ver comanda completa' : undefined}
25	      className={`bg-[#1A1A1A] border rounded-2xl overflow-hidden ${podeAbrirComanda ? 'cursor-pointer hover:border-[#FF441F]/60' : ''} ${posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30' : item.status === 'enviado' ? 'border-blue-500/40' : 'border-[#2A2A2A]'}`}>
26	      {item.garcom && (
27	        <div className="bg-white px-4 py-2">
28	          <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
29	        </div>
30	      )}
31	      <div className="p-4">
32	      <div className="flex items-start justify-between mb-1 gap-2">
33	        <div className="flex items-start gap-2">
34	          <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
35	            {posicao}
36	          </span>
37	          <div className="leading-tight">
38	            <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
39	            <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
40	          </div>
41	        </div>
42	        <button onClick={(e) => { e.stopPropagation(); onReimprimir(item); }}
43	          className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
44	          <Icon name="Printer" size={11} /> Reimpressão
45	        </button>
46	      </div>
47	      {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
48	      {item.observacao && <p className="text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">Obs: {item.observacao}</p>}
49	      <div className="flex items-center gap-2 text-base font-bold text-yellow-400 mb-2">
50	        <Icon name="MapPin" size={14} />
51	        <span>{item.mesa && item.cliente ? `${item.mesa} • ${item.cliente}` : item.mesa ?? item.cliente ?? (item.tipo === 'delivery' ? `Pedido #${item.order_id}` : 'Avulsa')}</span>
52	        {item.numero_comanda && (
53	          <>
54	            <span className="text-[#71717A]">•</span>
55	            <span>Comanda #{item.numero_comanda}</span>
56	          </>
57	        )}
58	        <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${item.tipo === 'delivery' ? 'bg-sky-500/20 text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
59	          {item.tipo === 'delivery' ? 'Delivery' : 'Salão'}
60	        </span>
61	      </div>
62	      <div className="flex items-center gap-3 text-[11px] font-mono mb-3">

